lessons.solution:
function summarize(minutes) { const seconds = minutes.filter(m => m >= 30).map(m => m * 60); const total = seconds.reduce((sum, x) => sum + x, 0); return { total, average: seconds.length ? total / seconds.length : null }; }
const result = summarize([20, 35, 45]);
